/** GM-reviewed, scoped quest publication desk. Player projection is only
 * generated by the protected service after canonical objective revalidation. */
import {EasyPlotsError} from '../contracts/errors.mjs';
import {secureUUID} from '../contracts/digest.mjs';
const el=(tag,cls='',text='')=>{const n=document.createElement(tag);if(cls)n.className=cls;n.textContent=String(text);return n;};
const sample={scope:'world',manifest:{id:'ep:quest-publication:example001',questId:'ep:quest:example001',publicId:'ep:quest-public:example001',title:'A new opportunity',observerIds:['ep:actor:hero001'],objectives:[{objectiveId:'ep:objective:example001',publicId:'ep:objective-public:example001',expectedRevision:1,text:'Meet the contact at the harbor',status:'active',recipientIds:['ep:actor:hero001']}]}};
export function makeGMQuestPublicationWindow(Base,{gameInstance,service}={}){
 if(typeof service?.prepare!=='function'||typeof service?.read!=='function'||typeof service?.approve!=='function'||typeof service?.project!=='function')
  throw new EasyPlotsError('QUEST_PROJECTION_DEPENDENCY','Protected quest projection service required');
 return class EasyPlotsGMQuestPublicationDesk extends Base {
  static DEFAULT_OPTIONS={id:'easy-plots-quest-publication-desk',window:{title:'Easy Plots — Quest Publication',resizable:true},position:{width:780,height:650}};
  #text=JSON.stringify(sample,null,2);#record=null;#confirmed=false;#message='';#busy=false;#projection=null;
  async _renderHTML(){
   const root=el('section','ep-editor ep-quest-publication');
   if(!gameInstance?.user?.isGM){root.append(el('p','ep-error','GM authority required'));return root;}
   root.append(el('h2','','Quest Publication'),el('p','ep-banner','Author only disclosed objective descriptions and their exact recipient lists. Each objective revision must still match canonical state at review and viewing time.'));
   const input=el('textarea','ep-input');input.dataset.field='publication';input.rows=16;input.value=this.#text;root.append(input);
   for(const [action,label] of [['prepare','Save proposed publication'],['read','Reload exact publication'],['approve','Approve audience view'],['preview','Preview for one recipient']]){
    const button=el('button','ep-button',label);button.type='button';button.dataset.action=action;
    if(action==='approve')button.disabled=!this.#confirmed||this.#record?.data?.state!=='draft';root.append(button);
   }
   const observer=el('input','ep-input');observer.dataset.field='observer';observer.placeholder='ep:actor:hero001';observer.maxLength=160;root.append(observer);
   const label=el('label','ep-field');const checked=el('input');checked.type='checkbox';checked.dataset.field='reviewed';checked.checked=this.#confirmed;
   label.append(checked,el('span','ep-label','I have reviewed every objective, public identifier and recipient allowlist'));root.append(label);
   if(this.#message)root.append(el('p','ep-notice',this.#message));
   if(this.#record){const panel=el('section','ep-panel');panel.append(el('h3','','Protected GM draft'),el('pre','ep-lab-output',JSON.stringify(this.#record,null,2)));root.append(panel);}
   if(this.#projection){const panel=el('section','ep-panel');panel.append(el('h3','','Recipient-safe preview'),el('pre','ep-projection-output',JSON.stringify(this.#projection,null,2)));root.append(panel);}
   root.addEventListener('input',ev=>{if(ev.target?.dataset?.field==='publication'){this.#record=null;this.#projection=null;this.#confirmed=false;
    root.querySelector('button[data-action="approve"]')?.setAttribute('disabled','');}});
   root.addEventListener('change',ev=>{if(ev.target?.dataset?.field==='reviewed'){this.#confirmed=ev.target.checked;
    root.querySelector('button[data-action="approve"]').disabled=!this.#confirmed||this.#record?.data?.state!=='draft';}});
   root.addEventListener('click',ev=>{const action=ev.target?.closest?.('button[data-action]')?.dataset?.action;if(!action||this.#busy)return;
    void(async()=>{this.#busy=true;try{
     if(!gameInstance?.user?.isGM)throw new EasyPlotsError('GM_REQUIRED','GM only');
     if(input.value.length>20_000)throw new EasyPlotsError('QUEST_PROJECTION_BUDGET','Publication draft exceeds budget');
     const payload=JSON.parse(input.value);this.#text=input.value;
     const scope=payload.scope??'world';const publicationId=payload.manifest?.id;
     if(action==='read'){this.#record=await service.read({scope,publicationId});this.#confirmed=false;}
     else if(action==='prepare'){
      const prior=await service.read({scope,publicationId});
      this.#record=await service.prepare({scope,manifest:payload.manifest,expectedRevision:prior?.revision??null,
       sourceEventId:`ep:event:quest_publish_${secureUUID().replaceAll('-','_')}`});this.#confirmed=false;
     }else if(action==='approve'){
      if(!this.#confirmed||!this.#record||this.#record.id!==publicationId||this.#record.data.state!=='draft')throw new EasyPlotsError('QUEST_REVIEW_REQUIRED','Saved, reviewed draft required');
      this.#record=await service.approve({scope,publicationId,expectedRevision:this.#record.revision,
       reviewEventId:`ep:event:quest_approval_${secureUUID().replaceAll('-','_')}`});this.#confirmed=false;
     }else{
      this.#projection=await service.project({scope,publicationId,observerId:observer.value.trim()});
      if(!this.#projection)throw new EasyPlotsError('QUEST_PROJECTION_UNAVAILABLE','No approved projection for that recipient');
     }
     this.#message=action==='approve'?'Approved. Recipient-safe projection available; no quest consequences executed.':
      action==='preview'?'Only authorized objective text appears below.':'Protected publication saved or loaded; no world effects performed.';
    }catch(error){this.#message=`${error.code??'QUEST_PROJECTION_ERROR'}: ${error.message}`;this.#confirmed=false;}
    finally{this.#busy=false;await this.render();}})();
   });
   return root;
  }
  _replaceHTML(result,content){content.replaceChildren(result);}
 };
}
